// ---- Agent webview IPC bridge (Step 4 of TRU-29) -------------------------
//
// The agent chat webview posts JSON messages back to Rust via wry's
// `with_ipc_handler`. The handler is set once at webview construction (wry
// has no API to swap it later), so it's stateless: it pushes parsed messages
// onto a global mpsc, and an Iced subscription drains the mpsc into typed
// `Event::AgentWebviewIpc` variants for the update loop to handle.
//
// Multi-tab routing: the JS side stamps every postMessage with the active
// tab's id (set by Rust via evaluate_script on tab activation). The
// dispatcher in update() reads tabId from the message and routes the prompt
// or stop signal to the right tab.
#[derive(Debug, Clone)]
pub enum AgentIpcMessage {
    Submit {
        tab_id: usize,
        text: String,
        /// Images pasted or dropped into the composer (TRU-140). `Err`
        /// carries why the page's images were malformed or over the caps;
        /// nothing is sent then.
        images: Result<Vec<ImageAttachment>, String>,
    },
    Stop {
        tab_id: usize,
    },
    /// The human withdrew a queued message (its × in the timeline) before
    /// Claude picked it up. Does not interrupt the running turn.
    Withdraw {
        tab_id: usize,
        id: String,
    },
    /// The human answered a runtime request (permission or question).
    Answer {
        tab_id: usize,
        request_id: String,
        decision: RuntimeDecision,
    },
    /// The human picked a Claude permission mode (chip or Shift+Tab).
    SetPermissionMode {
        tab_id: usize,
        mode: String,
    },
    /// The human picked a model on the composer's model chip (TRU-143).
    SetModel {
        tab_id: usize,
        model: String,
    },
    /// The human picked an effort level; `None` is the model's default.
    SetEffort {
        tab_id: usize,
        effort: Option<String>,
    },
    /// The checkout chip's menu opened and wants fresh choices.
    CheckoutContext {
        tab_id: usize,
    },
    /// The human picked a directory on the checkout chip.
    SetCheckout {
        tab_id: usize,
        path: PathBuf,
    },
    /// The Review… popover opened and wants its git defaults (TRU-142).
    ReviewContext {
        tab_id: usize,
    },
    /// The Review… popover was submitted. `Err` carries why the page's
    /// request could not be read.
    ReviewRequest {
        tab_id: usize,
        request: Result<gitterm::review::ReviewRequest, String>,
    },
    /// The popover's Consult… kind was submitted (TRU-142 S5).
    ConsultRequest {
        tab_id: usize,
        request: Result<gitterm::review::ConsultRequest, String>,
    },
    /// A delegation card's Send to Claude, with the ticked finding ids.
    DelegationSend {
        tab_id: usize,
        delegation_id: String,
        finding_ids: Vec<String>,
    },
    DelegationRerun {
        tab_id: usize,
        delegation_id: String,
    },
    DelegationDismiss {
        tab_id: usize,
        delegation_id: String,
    },
    /// A worker card's Open worker tab (TRU-142 S6).
    DelegationOpenWorker {
        tab_id: usize,
        delegation_id: String,
    },
    /// A finding's `file:line` was clicked; relative to the tab's checkout.
    OpenFile {
        tab_id: usize,
        path: PathBuf,
    },
    /// A message from the review pane's page on the Viewer (TRU-178).
    Review(gitterm::review_pane::ReviewIpc),
    /// An edit card's Open in review (TRU-179): the absolute file it edited.
    OpenReview {
        tab_id: usize,
        path: PathBuf,
    },
    /// A global shortcut typed while the chat page had keyboard focus, so
    /// the key never reached the Iced key handler (TRU-140). Only chords
    /// `global_shortcut` knows get here.
    HostKey {
        key: Key,
        modifiers: Modifiers,
    },
    /// Cmd+V typed in tab `tab_id`'s chat page (TRU-140). With no Edit
    /// menu WebKit does nothing with it, so the app sends the page the
    /// native `paste:` action.
    PastePage {
        tab_id: usize,
    },
    /// "Continue here" on a V5 conversation the empty chat tab was offered
    /// (TRU-183).
    V5Continue {
        tab_id: usize,
        session_id: String,
    },
}

/// Where a delegation request came from, so its acceptance or refusal
/// reaches whoever asked (TRU-142).
#[derive(Debug, Clone)]
pub enum DelegationOrigin {
    /// A `review_request` / `consult_request` tool call.
    Mcp(TaskControlReply),
    /// The chat page of this tab (Review… popover, Re-run).
    Page(usize),
}

static AGENT_IPC_TX: OnceLock<tokio::sync::mpsc::UnboundedSender<AgentIpcMessage>> =
    OnceLock::new();
static AGENT_IPC_RX: OnceLock<
    Mutex<Option<tokio::sync::mpsc::UnboundedReceiver<AgentIpcMessage>>>,
> = OnceLock::new();

fn init_agent_ipc_channel() {
    AGENT_IPC_TX.get_or_init(|| {
        let (tx, rx) = tokio::sync::mpsc::unbounded_channel::<AgentIpcMessage>();
        let _ = AGENT_IPC_RX.set(Mutex::new(Some(rx)));
        tx
    });
}

/// Iced subscription that drains the global IPC mpsc into typed events.
/// Built once on first poll (function pointer, no captures); the receiver is
/// taken out of `AGENT_IPC_RX` at that point and lives inside the stream
/// for the rest of the process. Subsequent rebuilds (which happen if the
/// subscription's identity hash changes) would receive an empty stream —
/// but the identity here is stable (no `with(...)` value), so we get exactly
/// one runner.
fn agent_ipc_stream() -> impl iced::futures::Stream<Item = Event> + Send + 'static {
    use iced::futures::StreamExt;
    let rx = AGENT_IPC_RX
        .get()
        .and_then(|m| m.lock().ok().and_then(|mut g| g.take()));
    let stream: tokio_stream::wrappers::UnboundedReceiverStream<AgentIpcMessage> = match rx {
        Some(rx) => tokio_stream::wrappers::UnboundedReceiverStream::new(rx),
        None => {
            // Channel already drained or not initialized — produce an empty
            // stream by closing a fresh channel immediately.
            let (_tx, rx) = tokio::sync::mpsc::unbounded_channel::<AgentIpcMessage>();
            tokio_stream::wrappers::UnboundedReceiverStream::new(rx)
        }
    };
    stream.map(Event::AgentWebviewIpc)
}

// ---- Agent-to-GitTerm task control bridge ---------------------------------
//
// The task MCP runs on Tokio, while TaskStore and every visible tab are owned
// by Iced's update loop. Keep that ownership boundary explicit: MCP requests
// cross this channel and are answered only after the app has applied them.
static TASK_CONTROL_TX: OnceLock<tokio::sync::mpsc::UnboundedSender<TaskControlEnvelope>> =
    OnceLock::new();
static TASK_CONTROL_RX: OnceLock<
    Mutex<Option<tokio::sync::mpsc::UnboundedReceiver<TaskControlEnvelope>>>,
> = OnceLock::new();

fn init_task_control_channel() -> tokio::sync::mpsc::UnboundedSender<TaskControlEnvelope> {
    TASK_CONTROL_TX
        .get_or_init(|| {
            let (tx, rx) = tokio::sync::mpsc::unbounded_channel::<TaskControlEnvelope>();
            let _ = TASK_CONTROL_RX.set(Mutex::new(Some(rx)));
            tx
        })
        .clone()
}

fn task_control_stream() -> impl iced::futures::Stream<Item = Event> + Send + 'static {
    use iced::futures::StreamExt;
    let rx = TASK_CONTROL_RX
        .get()
        .and_then(|receiver| receiver.lock().ok().and_then(|mut slot| slot.take()));
    let stream = match rx {
        Some(rx) => tokio_stream::wrappers::UnboundedReceiverStream::new(rx),
        None => {
            let (_tx, rx) = tokio::sync::mpsc::unbounded_channel::<TaskControlEnvelope>();
            tokio_stream::wrappers::UnboundedReceiverStream::new(rx)
        }
    };
    stream.map(Event::TaskControlRequested)
}

#[derive(Clone)]
struct BrowserTelemetrySubscriptionData {
    id: u64,
    browser: BrowserControlService,
    changes: tokio::sync::watch::Receiver<u64>,
}

impl BrowserTelemetrySubscriptionData {
    fn new(browser: BrowserControlService) -> Self {
        Self {
            id: browser.telemetry_subscription_id(),
            changes: browser.telemetry_changes(),
            browser,
        }
    }
}

impl Hash for BrowserTelemetrySubscriptionData {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.id.hash(state);
    }
}

fn browser_telemetry_stream(
    data: &BrowserTelemetrySubscriptionData,
) -> iced::futures::stream::BoxStream<'static, Event> {
    use iced::futures::{SinkExt, StreamExt};

    let browser = data.browser.clone();
    let mut changes = data.changes.clone();
    iced::stream::channel(8, async move |mut output| {
        while changes.changed().await.is_ok() {
            let telemetry = browser.telemetry().await;
            if output
                .send(Event::BrowserTelemetryLoaded(telemetry))
                .await
                .is_err()
            {
                break;
            }
        }
    })
    .boxed()
}

/// Push one `AgentEvent` into tab `tab_id`'s chat page via
/// `window.__appendEvent(...)`, visible or hidden. No-op if the tab has no
/// live page; its buffer is replayed when the page is (re)created.
fn push_agent_event_to_webview(tab_id: usize, ev: &tab::AgentEvent) {
    if !webview::is_active(WebviewSurface::Agent(tab_id)) {
        return;
    }
    let Some(payload) = ev.webview_payload() else {
        return;
    };
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        &format!("window.__appendEvent({payload})"),
    );
}

/// Replay a tab's whole conversation buffer into its page in one script call.
/// The page renders it without live timing (elapsed counters, auto-follow
/// jitter). `cards` are the tab's delegation cards (TRU-142): they are not in
/// the conversation, so they follow it; a card whose anchor is in the
/// conversation lands at the anchor, any other at the end.
fn replay_agent_conversation_in_webview(
    tab_id: usize,
    conversation: &[tab::AgentEvent],
    cards: Vec<serde_json::Value>,
) {
    let payloads: Vec<serde_json::Value> = conversation
        .iter()
        .filter_map(tab::AgentEvent::webview_payload)
        .chain(cards)
        .collect();
    let json = serde_json::Value::Array(payloads);
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        &format!("window.__replay({json})"),
    );
}

/// A CLI terminal tab's transcript as the Chats overview reads it (TRU-154):
/// the file's mtime and size when last checked, its gist, and the ask it
/// leaves open (a Claude transcript's tool call with no result yet). A
/// Claude transcript is read incrementally: `offset` is the end of the
/// last whole line read, `tracker` what those lines said.
#[derive(Debug, Clone)]
pub struct TranscriptGist {
    mtime: std::time::SystemTime,
    size: u64,
    offset: u64,
    tracker: Option<chat_summary::TranscriptTracker>,
    gist: chat_overview::ChatGist,
    pending: Option<chat_summary::WaitingAsk>,
}

/// One transcript the visible Chats overview follows: when it was last
/// checked, whether a check is out, and what the last read found.
#[derive(Debug, Default)]
struct OverviewTranscript {
    checked_at: Option<Instant>,
    in_flight: bool,
    loaded: Option<TranscriptGist>,
}

/// Bytes read at a time from a transcript; a long session's runs to a
/// hundred MB and more.
const TRANSCRIPT_READ_CHUNK: usize = 4 * 1024 * 1024;

/// Hand `on_lines` the whole lines of `path` from byte `offset` on, a
/// bounded chunk at a time, and return the offset after the last whole
/// line. A line still being written is left for the next read.
fn read_whole_lines_from(
    path: &Path,
    offset: u64,
    mut on_lines: impl FnMut(&str),
) -> std::io::Result<u64> {
    use std::io::{Seek, SeekFrom};
    let mut file = std::fs::File::open(path)?;
    file.seek(SeekFrom::Start(offset))?;
    let mut consumed = offset;
    let mut partial: Vec<u8> = Vec::new();
    let mut buf = vec![0u8; TRANSCRIPT_READ_CHUNK];
    loop {
        let read = file.read(&mut buf)?;
        if read == 0 {
            return Ok(consumed);
        }
        partial.extend_from_slice(&buf[..read]);
        if let Some(end) = partial.iter().rposition(|byte| *byte == b'\n') {
            let whole: Vec<u8> = partial.drain(..=end).collect();
            consumed += whole.len() as u64;
            on_lines(&String::from_utf8_lossy(&whole));
        }
    }
}

/// Check a CLI chat's transcript for the Chats overview against what the
/// last check found (`last`): `Ok(None)` while its mtime and size have not
/// moved. A Claude transcript's new whole lines are read and fed to the
/// last check's tracker (all of it again only when the file shrank); Codex
/// and Pi have only the preview tail, so their gist is the ask and the
/// reply, read from the tail again. Blocking; run off the UI thread.
fn load_transcript_gist(
    path: &Path,
    backend: chats::ChatBackend,
    last: Option<TranscriptGist>,
) -> Result<Option<TranscriptGist>, String> {
    let meta = std::fs::metadata(path).map_err(|err| format!("cannot stat: {err}"))?;
    let mtime = meta
        .modified()
        .map_err(|err| format!("no modification time: {err}"))?;
    let size = meta.len();
    if last
        .as_ref()
        .is_some_and(|last| last.mtime == mtime && last.size == size)
    {
        return Ok(None);
    }
    match backend {
        chats::ChatBackend::Claude => {
            let (mut tracker, offset) = match last {
                Some(TranscriptGist {
                    tracker: Some(tracker),
                    offset,
                    ..
                }) if offset <= size => (tracker, offset),
                _ => (chat_summary::TranscriptTracker::default(), 0),
            };
            let offset = read_whole_lines_from(path, offset, |lines| {
                let events: Vec<tab::AgentEvent> =
                    gitterm::harness::transcript::parse_claude_transcript(lines)
                        .into_iter()
                        .map(tab::AgentEvent::from)
                        .collect();
                tracker.feed(&events);
            })
            .map_err(|err| format!("cannot read: {err}"))?;
            Ok(Some(TranscriptGist {
                mtime,
                size,
                offset,
                gist: tracker.gist(),
                pending: tracker.pending(),
                tracker: Some(tracker),
            }))
        }
        chats::ChatBackend::Codex | chats::ChatBackend::Pi => {
            let preview = chats::load_preview(path, backend);
            Ok(Some(TranscriptGist {
                mtime,
                size,
                offset: 0,
                tracker: None,
                gist: chat_summary::gist(&chat_summary::digest_messages(&preview.messages)),
                pending: None,
            }))
        }
    }
}

/// The summary (TRU-155) of a conversation read back from its transcript.
/// Blocking-sized for a long transcript; run off the UI thread.
fn chat_digest_from_timeline(
    timeline: Vec<gitterm::harness::transcript::TimedEntry>,
) -> chat_summary::ChatDigest {
    let events: Vec<tab::AgentEvent> = timeline
        .into_iter()
        .map(|timed| tab::AgentEvent::from(timed.entry))
        .collect();
    chat_summary::digest(&events)
}

/// A transcript read-back as a chat timeline, with each delegation card's
/// anchor put back where the card was requested
/// (`delegations::history_anchor_positions`).
fn history_timeline(
    entries: Vec<gitterm::harness::transcript::TimedEntry>,
    delegations: &[(String, String)],
) -> Vec<tab::AgentEvent> {
    let anchors = gitterm::delegations::history_anchor_positions(&entries, delegations);
    let mut anchors = anchors.into_iter().peekable();
    let mut timeline = Vec::with_capacity(entries.len() + delegations.len());
    for (index, timed) in entries.into_iter().enumerate() {
        while let Some((_, id)) = anchors.next_if(|(at, _)| *at == index) {
            timeline.push(tab::AgentEvent::Other(
                gitterm::delegations::anchor_payload(&id),
            ));
        }
        let at_ms = timed
            .at
            .as_deref()
            .and_then(|at| chrono::DateTime::parse_from_rfc3339(at).ok())
            .map(|at| at.timestamp_millis());
        let event = tab::AgentEvent::from(timed.entry);
        let started = tab::subagent_started(&event).map(str::to_string);
        timeline.push(event);
        if let (Some(parent), Some(at_ms)) = (started, at_ms) {
            timeline.push(tab::AgentEvent::Other(tab::subagent_started_at(
                &parent, at_ms,
            )));
        }
    }
    timeline.extend(
        anchors.map(|(_, id)| tab::AgentEvent::Other(gitterm::delegations::anchor_payload(&id))),
    );
    timeline
}

/// `App::log_terminal_failure` for the bulk recreate, which holds the
/// workspaces mutably and so logs without the per-tab summary.
fn log_terminal_recreate_failure(cwd: &Path, error: &std::io::Error) {
    let usage = gitterm::resource_watch::fd_usage()
        .map(|usage| usage.describe())
        .unwrap_or_else(|e| format!("usage unknown: {e}"));
    let line = format!(
        "FAILED to recreate a terminal in {}: {error}; {usage}",
        cwd.display()
    );
    eprintln!("[resource] {line}");
    gitterm::resource_watch::append_log(&config::global_config_dir(), &line);
}

/// Queue dictated `text` for chat tab `tab_id` until its page is built.
/// Successive dictations join exactly as they do in a terminal, which gets
/// each transcript verbatim with no separator.
#[cfg(feature = "stt")]
fn hold_composer_dictation(held: &mut HashMap<usize, String>, tab_id: usize, text: &str) {
    held.entry(tab_id).or_default().push_str(text);
}

/// Tell a freshly built chat page which tab it belongs to. The page tags every
/// IPC message with this id so the Rust dispatcher routes the prompt/stop to
/// the right tab; each tab has its own page, so this runs once per page.
/// `permission_mode` is the Claude tab's configured mode (what the next spawn
/// passes); the replayed buffer's `ready` and `permission_mode_changed` events
/// override it. `None` (pi tabs) hides the mode chip. `composer` carries the
/// Claude tab's configured model and effort and its checkout chip state
/// (`None` for pi tabs hides those chips). `guidelines` shows the change
/// guidelines marker (TRU-174).
fn set_agent_webview_tab_id(
    tab_id: usize,
    permission_mode: Option<&str>,
    composer: Option<&serde_json::Value>,
    guidelines: bool,
) {
    let mode = serde_json::to_string(&permission_mode).unwrap_or_else(|e| {
        eprintln!("[agent-webview] tab {tab_id}: cannot encode mode {permission_mode:?}: {e}");
        "null".to_string()
    });
    let composer = composer.map_or_else(|| "null".to_string(), |c| c.to_string());
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        &format!("window.__setTabId({tab_id}, {mode}, {composer}, {guidelines})"),
    );
}

/// Show or hide a chat page's change guidelines marker (TRU-174).
fn push_guidelines_marker(tab_id: usize, on: bool) {
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        &format!("window.__setGuidelines({on})"),
    );
}

/// GitTerm's change guidelines for an agent starting now in `cwd`
/// (TRU-174); `None` when switched off or unreadable (logged).
fn launch_guidelines(cwd: &Path, workspace_off: bool) -> Option<gitterm::guidelines::Guidelines> {
    gitterm::guidelines::for_launch(&config::global_config_dir(), cwd, workspace_off)
}

/// What an agent starting now in `cwd` gets appended: the guidelines and,
/// in a piece of work, the documents note naming `places` (TRU-191). The
/// work's docs folder is created here, as the agent starts; a failure is
/// logged and the note still names it.
fn launch_instructions(
    cwd: &Path,
    workspace_off: bool,
    places: Option<&gitterm::guidelines::DocumentPlaces>,
) -> Option<gitterm::guidelines::Guidelines> {
    if let Some(places) = places {
        if let Err(error) = std::fs::create_dir_all(&places.docs_dir) {
            eprintln!(
                "[guidelines] cannot create the work's docs folder {}: {error}",
                places.docs_dir.display()
            );
        }
    }
    gitterm::guidelines::with_documents(
        launch_guidelines(cwd, workspace_off),
        places,
        &config::instance_config_dir(),
    )
}

/// The document places of a saved workspace entry (a workspace not open
/// yet): a work entry owns chats; its home is where they start.
fn config_document_places(cfg: &WorkspaceConfig) -> Option<gitterm::guidelines::DocumentPlaces> {
    let local = matches!(
        cfg.location,
        None | Some(config::WorkspaceLocationConfig::Local { .. })
    ) && cfg.remote_session.is_none();
    gitterm::guidelines::document_places(
        !cfg.chats.is_empty(),
        local,
        Path::new(cfg.home_dir()),
        cfg.decisions_repo.as_deref().map(Path::new),
    )
}

/// A terminal startup command with the guidelines (and the documents note
/// of `places`) added when it starts `claude`, `pi` or `codex`. Other
/// commands are not inspected, so they never read the guidelines file.
fn terminal_command_with_guidelines(
    command: &str,
    cwd: &Path,
    workspace_off: bool,
    places: Option<&gitterm::guidelines::DocumentPlaces>,
) -> String {
    // shortcut: the added option is POSIX-quoted, so Windows terminals
    // (cmd, PowerShell) launch without the guidelines until the quoting is
    // per-shell.
    if cfg!(target_os = "windows") {
        return command.to_string();
    }
    if !gitterm::guidelines::starts_a_harness(command) {
        return command.to_string();
    }
    match launch_instructions(cwd, workspace_off, places) {
        Some(guidelines) => gitterm::guidelines::configure_terminal_command(command, &guidelines),
        None => command.to_string(),
    }
}

/// Update a chat page's checkout chip (choices, label, lock).
fn push_checkout_state_to_webview(tab_id: usize, checkout: &serde_json::Value) {
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        &format!("window.__setCheckout({checkout})"),
    );
}

/// Show a transient note in a tab's chat page (not recorded in the
/// conversation buffer), e.g. why a Review… request was not sent.
fn agent_webview_note(tab_id: usize, text: &str) {
    let text = serde_json::Value::String(text.to_string());
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        &format!("window.__reviewNote({text})"),
    );
}

/// Show, or with `None` clear, the note offering an empty chat tab its V5
/// conversations above the composer (TRU-183).
fn push_v5_offer(tab_id: usize, offer: Option<&serde_json::Value>) {
    let offer = offer.map_or_else(|| "null".to_string(), |offer| offer.to_string());
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        &format!("window.__setV5Offer({offer})"),
    );
}

/// Why "Continue here" did not bind the tab, shown in the V5 note.
fn push_v5_offer_error(tab_id: usize, text: &str) {
    let text = serde_json::Value::String(text.to_string());
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        &format!("window.__setV5OfferError({text})"),
    );
}

/// Reset a tab's chat page: clears all rendered messages and sets status to
/// Idle.
fn reset_agent_webview(tab_id: usize) {
    webview::evaluate_script(
        WebviewSurface::Agent(tab_id),
        "window.__resetConversation()",
    );
}

/// A chord with the same app-wide meaning whatever has focus. The Iced key
/// handler acts on these (resolving them against app state: which tabs are
/// visible, how many workspaces exist, which overlay is open), and a chat
/// page forwards exactly these when it has keyboard focus, since its keys
/// never reach the handler (TRU-140).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GlobalShortcut {
    /// Ctrl+Space: start or stop dictation (`stt` builds).
    Dictation,
    /// Ctrl+1…9: the nth workspace.
    SelectWorkspace(usize),
    /// Cmd+1…9: the nth visible tab.
    SelectTab(usize),
    /// Cmd+Shift+U: the Usage view.
    UsageView,
    /// Cmd+T: the task switcher.
    TaskSwitcher,
    /// Cmd+Shift+O: the Chats overview (TRU-154).
    ChatsOverview,
    /// Escape with no modifiers: dismiss the topmost app overlay. The key
    /// handler resolves Escape against app state itself; it is listed here
    /// so a chat page can forward it.
    Escape,
}

/// Which global shortcut `key` with `modifiers` is, if any. Pure, so the
/// Iced key handler and the chat page's forwarded keys share one table.
fn global_shortcut(key: &Key, modifiers: Modifiers) -> Option<GlobalShortcut> {
    match key.as_ref() {
        Key::Named(key::Named::Space)
            if modifiers.control()
                && !modifiers.command()
                && !modifiers.shift()
                && !modifiers.alt() =>
        {
            Some(GlobalShortcut::Dictation)
        }
        Key::Named(key::Named::Escape) if modifiers.is_empty() => Some(GlobalShortcut::Escape),
        Key::Character(c) => {
            let digit = c.parse::<usize>().ok().filter(|n| (1..=9).contains(n));
            if let Some(num) = digit {
                if modifiers.control() && !modifiers.command() {
                    return Some(GlobalShortcut::SelectWorkspace(num));
                }
                if modifiers.command() {
                    return Some(GlobalShortcut::SelectTab(num));
                }
                return None;
            }
            if modifiers.command() && modifiers.shift() && c.eq_ignore_ascii_case("u") {
                return Some(GlobalShortcut::UsageView);
            }
            if modifiers.command()
                && modifiers.shift()
                && !modifiers.control()
                && !modifiers.alt()
                && c.eq_ignore_ascii_case("o")
            {
                return Some(GlobalShortcut::ChatsOverview);
            }
            if modifiers.command()
                && !modifiers.shift()
                && !modifiers.control()
                && c.eq_ignore_ascii_case("t")
            {
                return Some(GlobalShortcut::TaskSwitcher);
            }
            None
        }
        _ => None,
    }
}

/// What a chord a chat page forwarded asks the app to do.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ForwardedKey {
    /// An app-wide chord, run through the Iced key handler.
    Global(GlobalShortcut),
    /// Cmd+V: paste into the page that forwarded it. Not a global shortcut:
    /// in the terminal Cmd+V is the terminal's own paste, which the Iced
    /// key handler leaves to iced_term.
    Paste,
}

/// Which forwarded chord `key` with `modifiers` is, if any: the chat page's
/// `isHostShortcut` allow-list as the host reads it. Pure, for tests.
fn forwarded_key(key: &Key, modifiers: Modifiers) -> Option<ForwardedKey> {
    if let Key::Character(c) = key.as_ref() {
        if c.eq_ignore_ascii_case("v")
            && modifiers.command()
            && !modifiers.shift()
            && !modifiers.control()
            && !modifiers.alt()
        {
            return Some(ForwardedKey::Paste);
        }
    }
    global_shortcut(key, modifiers).map(ForwardedKey::Global)
}

/// Read a chord a chat page forwarded (`{type: "hostkey", key, code, meta,
/// ctrl, shift, alt}`) as the key and modifiers the Iced key handler would
/// have seen. `key` is the DOM `KeyboardEvent.key` (the logical key, as
/// Iced reports it); `code` is not needed.
fn hostkey_chord(value: &serde_json::Value) -> Result<(Key, Modifiers), String> {
    let name = value.get("key").and_then(|v| v.as_str()).ok_or("no key")?;
    let key = match name {
        "Escape" => Key::Named(key::Named::Escape),
        " " => Key::Named(key::Named::Space),
        c if c.chars().count() == 1 => Key::Character(c.into()),
        other => return Err(format!("unsupported key {other:?}")),
    };
    let mut modifiers = Modifiers::empty();
    for (field, flag) in [
        ("meta", Modifiers::LOGO),
        ("ctrl", Modifiers::CTRL),
        ("shift", Modifiers::SHIFT),
        ("alt", Modifiers::ALT),
    ] {
        match value.get(field) {
            Some(serde_json::Value::Bool(true)) => modifiers.insert(flag),
            Some(serde_json::Value::Bool(false)) => {}
            _ => return Err(format!("no boolean {field}")),
        }
    }
    Ok((key, modifiers))
}

/// Build the IPC handler closure to install at agent-webview creation. Parses
/// each `window.ipc.postMessage(...)` body and forwards as a typed message
/// into the global IPC channel for the Iced subscription to pick up.
fn agent_ipc_handler() -> webview::IpcHandler {
    Box::new(|body: String| {
        let Some(tx) = AGENT_IPC_TX.get() else {
            eprintln!("[agent-ipc] tx not initialized; dropping {}", body);
            return;
        };
        let Ok(value) = serde_json::from_str::<serde_json::Value>(&body) else {
            eprintln!("[agent-ipc] non-JSON body: {}", body);
            return;
        };
        let tab_id = value
            .get("tabId")
            .and_then(|v| v.as_u64())
            .map(|n| n as usize);
        let kind = value.get("type").and_then(|v| v.as_str()).unwrap_or("");
        let Some(tab_id) = tab_id else {
            eprintln!("[agent-ipc] missing tabId in {}", body);
            return;
        };
        let msg = match kind {
            "submit" => {
                let text = value
                    .get("text")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let images = match value.get("images") {
                    None | Some(serde_json::Value::Null) => Ok(Vec::new()),
                    Some(images) => serde_json::from_value::<Vec<ImageAttachment>>(images.clone())
                        .map_err(|e| format!("the attached images were malformed ({e})")),
                }
                .and_then(|images| gitterm::harness::validate_images(&images).map(|()| images));
                AgentIpcMessage::Submit {
                    tab_id,
                    text,
                    images,
                }
            }
            "stop" => AgentIpcMessage::Stop { tab_id },
            "withdraw" => {
                let Some(id) = value.get("id").and_then(|v| v.as_str()) else {
                    eprintln!("[agent-ipc] withdraw without id: {}", body);
                    return;
                };
                AgentIpcMessage::Withdraw {
                    tab_id,
                    id: id.to_string(),
                }
            }
            "answer" => {
                let Some(request_id) = value.get("requestId").and_then(|v| v.as_str()) else {
                    eprintln!("[agent-ipc] answer without requestId: {}", body);
                    return;
                };
                let decision = match value
                    .get("decision")
                    .cloned()
                    .map(serde_json::from_value::<RuntimeDecision>)
                {
                    Some(Ok(decision)) => decision,
                    Some(Err(e)) => {
                        eprintln!("[agent-ipc] bad decision in {}: {}", body, e);
                        return;
                    }
                    None => {
                        eprintln!("[agent-ipc] answer without decision: {}", body);
                        return;
                    }
                };
                AgentIpcMessage::Answer {
                    tab_id,
                    request_id: request_id.to_string(),
                    decision,
                }
            }
            "set_permission_mode" => {
                let Some(mode) = value.get("mode").and_then(|v| v.as_str()) else {
                    eprintln!("[agent-ipc] set_permission_mode without mode: {}", body);
                    return;
                };
                AgentIpcMessage::SetPermissionMode {
                    tab_id,
                    mode: mode.to_string(),
                }
            }
            "set_model" => {
                let Some(model) = value.get("model").and_then(|v| v.as_str()) else {
                    eprintln!("[agent-ipc] set_model without model: {}", body);
                    return;
                };
                AgentIpcMessage::SetModel {
                    tab_id,
                    model: model.to_string(),
                }
            }
            "set_effort" => {
                let effort = match value.get("effort") {
                    Some(serde_json::Value::Null) => None,
                    Some(serde_json::Value::String(level)) => Some(level.clone()),
                    _ => {
                        eprintln!("[agent-ipc] set_effort without effort: {}", body);
                        return;
                    }
                };
                AgentIpcMessage::SetEffort { tab_id, effort }
            }
            "checkout_context" => AgentIpcMessage::CheckoutContext { tab_id },
            "set_checkout" => {
                let Some(path) = value.get("path").and_then(|v| v.as_str()) else {
                    eprintln!("[agent-ipc] set_checkout without path: {}", body);
                    return;
                };
                AgentIpcMessage::SetCheckout {
                    tab_id,
                    path: PathBuf::from(path),
                }
            }
            "review_context" => AgentIpcMessage::ReviewContext { tab_id },
            "review_request" => AgentIpcMessage::ReviewRequest {
                tab_id,
                request: serde_json::from_value(value.clone())
                    .map_err(|e| format!("could not read the review request: {e}")),
            },
            "consult_request" => AgentIpcMessage::ConsultRequest {
                tab_id,
                request: serde_json::from_value(value.clone())
                    .map_err(|e| format!("could not read the consult request: {e}")),
            },
            "delegation_send"
            | "delegation_rerun"
            | "delegation_dismiss"
            | "delegation_open_worker" => {
                let Some(delegation_id) = value
                    .get("delegationId")
                    .and_then(|v| v.as_str())
                    .map(str::to_string)
                else {
                    eprintln!("[agent-ipc] {kind} without delegationId: {body}");
                    return;
                };
                match kind {
                    "delegation_send" => {
                        let finding_ids = match value.get("findingIds") {
                            None | Some(serde_json::Value::Null) => Vec::new(),
                            Some(ids) => match serde_json::from_value::<Vec<String>>(ids.clone()) {
                                Ok(ids) => ids,
                                Err(e) => {
                                    eprintln!("[agent-ipc] bad findingIds in {body}: {e}");
                                    return;
                                }
                            },
                        };
                        AgentIpcMessage::DelegationSend {
                            tab_id,
                            delegation_id,
                            finding_ids,
                        }
                    }
                    "delegation_rerun" => AgentIpcMessage::DelegationRerun {
                        tab_id,
                        delegation_id,
                    },
                    "delegation_open_worker" => AgentIpcMessage::DelegationOpenWorker {
                        tab_id,
                        delegation_id,
                    },
                    _ => AgentIpcMessage::DelegationDismiss {
                        tab_id,
                        delegation_id,
                    },
                }
            }
            "open_file" => {
                let Some(path) = value.get("path").and_then(|v| v.as_str()) else {
                    eprintln!("[agent-ipc] open_file without path: {body}");
                    return;
                };
                AgentIpcMessage::OpenFile {
                    tab_id,
                    path: PathBuf::from(path),
                }
            }
            "v5_continue" => {
                let Some(session_id) = value
                    .get("sessionId")
                    .and_then(|v| v.as_str())
                    .filter(|id| !id.is_empty())
                else {
                    eprintln!("[agent-ipc] v5_continue without sessionId: {body}");
                    return;
                };
                AgentIpcMessage::V5Continue {
                    tab_id,
                    session_id: session_id.to_string(),
                }
            }
            "open_review" => match gitterm::review_pane::chat_review_path(&value) {
                Ok(path) => AgentIpcMessage::OpenReview { tab_id, path },
                Err(e) => {
                    eprintln!("[agent-ipc] tab {tab_id}: {e}");
                    return;
                }
            },
            "hostkey" => {
                let (key, modifiers) = match hostkey_chord(&value) {
                    Ok(chord) => chord,
                    Err(e) => {
                        eprintln!("[agent-ipc] tab {tab_id}: bad hostkey ({e}): {body}");
                        return;
                    }
                };
                match forwarded_key(&key, modifiers) {
                    Some(ForwardedKey::Global(_)) => AgentIpcMessage::HostKey { key, modifiers },
                    Some(ForwardedKey::Paste) => AgentIpcMessage::PastePage { tab_id },
                    None => {
                        eprintln!(
                            "[agent-ipc] tab {tab_id}: ignoring hostkey {key:?} {modifiers:?}, not a forwarded chord"
                        );
                        return;
                    }
                }
            }
            "open_url" => {
                let url = value.get("url").and_then(|v| v.as_str()).unwrap_or("");
                // Links in agent output open in the browser, never inside
                // the chat webview (which would navigate the chat away).
                if url.starts_with("https://") || url.starts_with("http://") {
                    if let Err(e) = std::process::Command::new("open").arg(url).spawn() {
                        eprintln!("[agent-ipc] open {} failed: {}", url, e);
                    }
                } else {
                    eprintln!("[agent-ipc] refusing to open non-http url {:?}", url);
                }
                return;
            }
            _ => {
                eprintln!("[agent-ipc] unknown type {:?}", kind);
                return;
            }
        };
        let _ = tx.send(msg);
    })
}

/// The Viewer surface's IPC handler, installed whatever the Viewer shows
/// first (wry cannot add one later). Only the review pane's page posts
/// (TRU-178); its messages join the agent IPC channel, and main.rs acts on
/// them only while that pane, with that token, is showing.
fn viewer_ipc_handler() -> webview::IpcHandler {
    Box::new(|body: String| {
        let Some(tx) = AGENT_IPC_TX.get() else {
            eprintln!("[review-ipc] tx not initialized; dropping {body}");
            return;
        };
        match gitterm::review_pane::parse_ipc(&body) {
            Ok(message) => {
                if tx.send(AgentIpcMessage::Review(message)).is_err() {
                    eprintln!("[review-ipc] channel closed; dropping {body}");
                }
            }
            Err(error) => eprintln!("[review-ipc] {error}"),
        }
    })
}

fn start_freeze_watchdog() {
    if !freeze_debug_enabled() {
        return;
    }

    // Store main thread's pthread ID for signaling
    #[cfg(unix)]
    {
        let tid = unsafe { libc::pthread_self() } as u64;
        MAIN_THREAD_ID.store(tid, std::sync::atomic::Ordering::Relaxed);

        // Install SIGUSR1 handler that prints backtrace
        unsafe {
            libc::signal(
                libc::SIGUSR1,
                freeze_backtrace_handler as *const () as libc::sighandler_t,
            );
        }
    }

    std::thread::Builder::new()
        .name("freeze-watchdog".to_string())
        .spawn(|| {
            let mut last_beat = 0u64;
            let mut stall_start: Option<std::time::Instant> = None;
            let mut backtrace_sent = false;
            let mut log_count = 0u32;
            loop {
                std::thread::sleep(Duration::from_millis(500));
                let current = MAIN_THREAD_HEARTBEAT.load(std::sync::atomic::Ordering::Relaxed);
                if current == last_beat {
                    // Main thread hasn't ticked
                    if stall_start.is_none() {
                        stall_start = Some(std::time::Instant::now());
                        backtrace_sent = false;
                        log_count = 0;
                    }
                    let elapsed = stall_start.unwrap().elapsed();

                    // Log the first few stall messages, then go quiet
                    if elapsed.as_secs() >= 2 && log_count < 10 {
                        log_count += 1;
                        let event_name = MAIN_THREAD_LAST_EVENT
                            .lock()
                            .ok()
                            .and_then(|g| g.clone())
                            .unwrap_or_else(|| "unknown".to_string());
                        eprintln!(
                            "[FREEZE-WATCHDOG] Main thread stalled for {:.1}s! Last event: {}",
                            elapsed.as_secs_f64(),
                            event_name
                        );
                    }

                    // Send SIGUSR1 at 5s to capture backtrace (once)
                    #[cfg(unix)]
                    if elapsed.as_secs() >= 5 && !backtrace_sent {
                        backtrace_sent = true;
                        let tid = MAIN_THREAD_ID.load(std::sync::atomic::Ordering::Relaxed);
                        if tid != 0 {
                            eprintln!(
                                "\n[FREEZE-WATCHDOG] ========================================"
                            );
                            eprintln!("[FREEZE-WATCHDOG] Capturing backtrace via SIGUSR1...");
                            eprintln!(
                                "[FREEZE-WATCHDOG] ========================================\n"
                            );
                            unsafe {
                                libc::pthread_kill(tid as libc::pthread_t, libc::SIGUSR1);
                            }
                            // Give the signal handler time to print before any more logs
                            std::thread::sleep(Duration::from_secs(2));
                        }
                    }

                    // After 10 logs, only log every 60s
                    if log_count >= 10 {
                        let secs = elapsed.as_secs();
                        if secs.is_multiple_of(60) {
                            eprintln!(
                                "[FREEZE-WATCHDOG] Still stalled after {}m. Force quit to restart.",
                                secs / 60
                            );
                        }
                        std::thread::sleep(Duration::from_millis(1500));
                    }
                } else {
                    if let Some(start) = stall_start.take() {
                        let dur = start.elapsed();
                        if dur.as_secs() >= 2 {
                            eprintln!(
                                "[FREEZE-WATCHDOG] Main thread recovered after {:.1}s stall",
                                dur.as_secs_f64()
                            );
                        }
                    }
                    last_beat = current;
                }
            }
        })
        .ok();
}

/// Signal handler: prints backtrace when SIGUSR1 is received on the main thread.
/// This runs IN the frozen main thread's context, so the backtrace shows exactly
/// where it's stuck.
///
/// IMPORTANT: This handler must be async-signal-safe. No heap allocation allowed!
/// `std::backtrace::Backtrace` and `format!()` allocate, so if the signal arrives
/// while the thread is inside malloc, it would deadlock/crash with
/// "BUG IN LIBMALLOC: ulock_wait failure".
///
/// Instead we use `libc::backtrace()` to capture raw frame pointers into a
/// stack-allocated buffer, then write hex addresses to stderr with `libc::write()`.
/// The addresses can be symbolicated later with:
///   atos -o target/release/gitterm -l 0x<load_addr> <addr1> <addr2> ...
#[cfg(unix)]
extern "C" fn freeze_backtrace_handler(_sig: libc::c_int) {
    unsafe {
        // All buffers on the stack — zero heap allocation
        let mut frames: [*mut libc::c_void; 128] = [std::ptr::null_mut(); 128];
        let n = libc::backtrace(frames.as_mut_ptr(), 128);

        let header = b"\n[FREEZE-WATCHDOG] === MAIN THREAD BACKTRACE (raw frames) ===\n";
        libc::write(2, header.as_ptr() as *const libc::c_void, header.len());

        // Write each frame address as hex, one per line
        // Format: "  [NN] 0xHHHHHHHHHHHHHHHH\n"
        let hex_chars = b"0123456789abcdef";
        for i in 0..n as usize {
            let addr = frames[i] as usize;
            // Build line in stack buffer: "  [NN] 0x________________\n"
            let mut line: [u8; 32] = [b' '; 32];
            // Frame index
            line[2] = b'[';
            if i >= 100 {
                line[3] = hex_chars[(i / 100) % 10];
                line[4] = hex_chars[(i / 10) % 10];
                line[5] = hex_chars[i % 10];
                line[6] = b']';
                line[7] = b' ';
                line[8] = b'0';
                line[9] = b'x';
            } else if i >= 10 {
                line[3] = hex_chars[(i / 10) % 10];
                line[4] = hex_chars[i % 10];
                line[5] = b']';
                line[6] = b' ';
                line[7] = b'0';
                line[8] = b'x';
            } else {
                line[3] = hex_chars[i % 10];
                line[4] = b']';
                line[5] = b' ';
                line[6] = b'0';
                line[7] = b'x';
            }
            // Write 16 hex digits for the address (always 64-bit)
            let hex_start = if i >= 100 {
                10
            } else if i >= 10 {
                9
            } else {
                8
            };
            for digit in 0..16 {
                let nibble = (addr >> (60 - digit * 4)) & 0xf;
                line[hex_start + digit] = hex_chars[nibble];
            }
            let line_len = hex_start + 16;
            line[line_len] = b'\n';
            libc::write(2, line.as_ptr() as *const libc::c_void, line_len + 1);
        }

        let footer = b"[FREEZE-WATCHDOG] === END BACKTRACE ===\n\n";
        libc::write(2, footer.as_ptr() as *const libc::c_void, footer.len());
    }
}

/// Record that the main thread processed an event
fn heartbeat(event_name: &str) {
    MAIN_THREAD_HEARTBEAT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if freeze_debug_enabled() {
        if let Ok(mut guard) = MAIN_THREAD_LAST_EVENT.try_lock() {
            *guard = Some(event_name.to_string());
        }
    }
}

/// Truncate a string to at most `max_bytes` bytes at a valid UTF-8 char boundary.
fn truncate_str(s: &str, max_bytes: usize) -> &str {
    if s.len() <= max_bytes {
        return s;
    }
    let mut end = max_bytes;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

/// Characters a session strip label shows before it is cut with "…".
const SESSION_TAB_LABEL_CHARS: usize = 20;

/// The session strip's label for a tab (TRU-172). A chat tab whose
/// conversation the chats index has titled reads as that title, so two
/// chats in one folder no longer both read as the folder name. Without a
/// title (a chat not indexed yet, a terminal tab) it is today's label:
/// the shell or harness title, attention markers stripped, a path cut to
/// its last component.
fn session_tab_label(
    chat_title: Option<&str>,
    display_title: &str,
    has_attention: bool,
    workspace_is_remote: bool,
) -> String {
    if let Some(title) = chat_title.map(str::trim).filter(|title| !title.is_empty()) {
        // Titles are free text (they may start with "/"), so no path
        // shortening; cut on chars, not bytes.
        if title.chars().count() > SESSION_TAB_LABEL_CHARS {
            let cut: String = title.chars().take(SESSION_TAB_LABEL_CHARS - 1).collect();
            return format!("{}…", cut.trim_end());
        }
        return title.to_string();
    }
    // Strip a leading "*" when attention (redundant with the visual
    // indicator) and shorten path-like titles to their last component.
    let display = if has_attention {
        display_title.trim_start_matches(['*', '✳']).trim_start()
    } else {
        display_title
    };
    let display = if !workspace_is_remote && (display.starts_with('/') || display.starts_with('~'))
    {
        std::path::Path::new(display)
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_else(|| display.to_string())
    } else {
        display.to_string()
    };
    if display.len() > SESSION_TAB_LABEL_CHARS {
        format!("{}…", truncate_str(&display, SESSION_TAB_LABEL_CHARS - 1))
    } else {
        display
    }
}

/// Percent-encode RFC 3986 reserved characters in a query-string value.
/// Used for `?plan=<name>` so plan filenames with spaces or punctuation
/// round-trip cleanly into the viewer's URL.
fn urlencoding_simple(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn freeze_debug_enabled() -> bool {
    FREEZE_DEBUG.load(std::sync::atomic::Ordering::Relaxed)
        || std::env::var("GITTERM_DEBUG_FREEZES").is_ok()
}

macro_rules! freeze_debug {
    ($($arg:tt)*) => {{
        if freeze_debug_enabled() {
            eprintln!("[FREEZE-DEBUG] {}", format_args!($($arg)*));
        }
    }};
}

macro_rules! freeze_time {
    ($label:expr, $block:block) => {{
        let _start = std::time::Instant::now();
        let result = $block;
        let _elapsed = _start.elapsed();
        if _elapsed > Duration::from_millis(100) {
            freeze_debug!("{} took {}ms", $label, _elapsed.as_millis());
        }
        result
    }};
}

// Menu item IDs stored globally for event matching
static MENU_IDS: OnceLock<MenuIds> = OnceLock::new();

#[derive(Debug)]
struct MenuIds {
    increase_terminal_font: muda::MenuId,
    decrease_terminal_font: muda::MenuId,
    increase_ui_font: muda::MenuId,
    decrease_ui_font: muda::MenuId,
    toggle_theme: muda::MenuId,
    toggle_terminal_log_mirroring: muda::MenuId,
    clear_terminal: muda::MenuId,
    open_plans_viewer: muda::MenuId,
}

fn setup_menu_bar() {
    // Create native macOS menu bar
    let menu = Menu::new();

    // App menu (GitTerm V6)
    let app_menu = Submenu::new(config::APP_NAME, true);
    app_menu
        .append_items(&[
            &PredefinedMenuItem::about(None, None),
            &PredefinedMenuItem::separator(),
            &PredefinedMenuItem::services(None),
            &PredefinedMenuItem::separator(),
            &PredefinedMenuItem::hide(None),
            &PredefinedMenuItem::hide_others(None),
            &PredefinedMenuItem::show_all(None),
            &PredefinedMenuItem::separator(),
            &PredefinedMenuItem::quit(None),
        ])
        .unwrap();

    // View menu (font size, theme)
    let view_menu = Submenu::new("View", true);

    // Terminal font submenu
    let terminal_font_menu = Submenu::new("Terminal Font", true);
    let increase_terminal_font = MenuItem::new(
        "Increase",
        true,
        Some(Accelerator::new(
            Some(muda::accelerator::Modifiers::META),
            muda::accelerator::Code::Equal,
        )),
    );
    let decrease_terminal_font = MenuItem::new(
        "Decrease",
        true,
        Some(Accelerator::new(
            Some(muda::accelerator::Modifiers::META),
            muda::accelerator::Code::Minus,
        )),
    );
    let clear_terminal = MenuItem::new(
        "Clear Terminal",
        true,
        Some(Accelerator::new(
            Some(muda::accelerator::Modifiers::META),
            muda::accelerator::Code::KeyK,
        )),
    );
    terminal_font_menu
        .append_items(&[
            &increase_terminal_font,
            &decrease_terminal_font,
            &clear_terminal,
        ])
        .unwrap();

    // UI font submenu
    let ui_font_menu = Submenu::new("Sidebar Font", true);
    let increase_ui_font = MenuItem::new(
        "Increase",
        true,
        Some(Accelerator::new(
            Some(muda::accelerator::Modifiers::META | muda::accelerator::Modifiers::SHIFT),
            muda::accelerator::Code::Equal,
        )),
    );
    let decrease_ui_font = MenuItem::new(
        "Decrease",
        true,
        Some(Accelerator::new(
            Some(muda::accelerator::Modifiers::META | muda::accelerator::Modifiers::SHIFT),
            muda::accelerator::Code::Minus,
        )),
    );
    ui_font_menu
        .append_items(&[&increase_ui_font, &decrease_ui_font])
        .unwrap();

    let toggle_theme = MenuItem::new(
        "Toggle Light/Dark Theme",
        true,
        Some(Accelerator::new(
            Some(muda::accelerator::Modifiers::META | muda::accelerator::Modifiers::SHIFT),
            muda::accelerator::Code::KeyT,
        )),
    );
    let toggle_terminal_log_mirroring = MenuItem::new(
        "Toggle Terminal Log Mirroring",
        true,
        Some(Accelerator::new(
            Some(muda::accelerator::Modifiers::META | muda::accelerator::Modifiers::SHIFT),
            muda::accelerator::Code::KeyL,
        )),
    );
    let open_plans_viewer = MenuItem::new(
        "Plans Viewer",
        true,
        Some(Accelerator::new(
            Some(muda::accelerator::Modifiers::META | muda::accelerator::Modifiers::SHIFT),
            muda::accelerator::Code::KeyP,
        )),
    );

    view_menu
        .append_items(&[
            &terminal_font_menu,
            &ui_font_menu,
            &PredefinedMenuItem::separator(),
            &toggle_theme,
            &toggle_terminal_log_mirroring,
            &PredefinedMenuItem::separator(),
            &open_plans_viewer,
        ])
        .unwrap();

    // No Edit menu. Its Cut/Copy/Paste key equivalents claim Cmd+C/V
    // before winit sees them, even with nothing to act on, so terminals
    // could not copy or paste. The chat page handles those chords itself
    // (`editingCommand` and the forwarded Cmd+V in agent_chat.html).

    // Window menu
    let window_menu = Submenu::new("Window", true);
    window_menu
        .append_items(&[
            &PredefinedMenuItem::minimize(None),
            &PredefinedMenuItem::maximize(None),
            &PredefinedMenuItem::separator(),
            &PredefinedMenuItem::fullscreen(None),
        ])
        .unwrap();

    menu.append_items(&[&app_menu, &view_menu, &window_menu])
        .unwrap();

    // Store menu IDs for event handling
    let _ = MENU_IDS.set(MenuIds {
        increase_terminal_font: increase_terminal_font.id().clone(),
        decrease_terminal_font: decrease_terminal_font.id().clone(),
        increase_ui_font: increase_ui_font.id().clone(),
        decrease_ui_font: decrease_ui_font.id().clone(),
        toggle_theme: toggle_theme.id().clone(),
        toggle_terminal_log_mirroring: toggle_terminal_log_mirroring.id().clone(),
        clear_terminal: clear_terminal.id().clone(),
        open_plans_viewer: open_plans_viewer.id().clone(),
    });

    // Initialize menu for macOS - this must happen after NSApp exists
    #[cfg(target_os = "macos")]
    menu.init_for_nsapp();

    // Leak the menu to keep it alive for the lifetime of the app
    Box::leak(Box::new(menu));
}

// === Speech-to-Text helpers ===

#[cfg(feature = "stt")]
const STT_MIN_RECORDING_SECONDS: f32 = 0.25;
#[cfg(feature = "stt")]
const STT_MIN_RMS: f32 = 0.001;
#[cfg(feature = "stt")]
const STT_MIN_PEAK: f32 = 0.01;

#[cfg(feature = "stt")]
fn stt_model_path() -> PathBuf {
    config::global_config_dir()
        .join("models")
        .join("ggml-base.en.bin")
}

#[cfg(feature = "stt")]
fn stt_audio_stats(samples: &[f32]) -> (f32, f32) {
    if samples.is_empty() {
        return (0.0, 0.0);
    }

    let mut sum_squares = 0.0f64;
    let mut peak = 0.0f32;
    for &sample in samples {
        let abs = sample.abs();
        peak = peak.max(abs);
        let sample = sample as f64;
        sum_squares += sample * sample;
    }

    let rms = (sum_squares / samples.len() as f64).sqrt() as f32;
    (rms, peak)
}

#[cfg(feature = "stt")]
fn stt_start_recording(audio_buffer: Arc<Mutex<Vec<f32>>>) -> Result<(cpal::Stream, u32), String> {
    use cpal::traits::{DeviceTrait, HostTrait, StreamTrait};

    let host = cpal::default_host();
    let default = host.default_input_device();
    let default_config = default.as_ref().map(|device| device.default_input_config());
    let (device, config) = match (default, default_config) {
        (Some(device), Some(Ok(config))) => (device, config),
        (_, default_err) => {
            // macOS can leave the default input pointing at a device that
            // has gone (a headset or iPhone mic that disconnected; seen
            // 2026-10-23). Record from the first input that answers instead.
            let reason = match default_err {
                Some(Err(e)) => format!("the default input device failed ({e})"),
                _ => "there is no default input device".to_string(),
            };
            let fallback = host
                .input_devices()
                .map_err(|e| format!("Failed to list input devices after {reason}: {e}"))?
                .find_map(|device| {
                    let config = device.default_input_config().ok()?;
                    Some((device, config))
                })
                .ok_or_else(|| format!("No working input device: {reason}"))?;
            eprintln!(
                "[STT] {reason}; recording from {} instead",
                fallback
                    .0
                    .name()
                    .unwrap_or_else(|_| "<unknown input device>".to_string())
            );
            fallback
        }
    };

    let sample_rate = config.sample_rate().0;
    let device_name = device
        .name()
        .unwrap_or_else(|_| "<unknown input device>".to_string());
    eprintln!(
        "[STT] Starting recording: device={} sample_rate={} channels={} format={:?}",
        device_name,
        sample_rate,
        config.channels(),
        config.sample_format()
    );

    // Clear existing buffer
    {
        let mut buf = audio_buffer.lock().unwrap();
        buf.clear();
    }

    let channels = config.channels() as usize;
    let buf = audio_buffer.clone();

    let stream = match config.sample_format() {
        cpal::SampleFormat::F32 => device
            .build_input_stream(
                &config.into(),
                move |data: &[f32], _: &cpal::InputCallbackInfo| {
                    let mut buf = buf.lock().unwrap();
                    // Convert to mono by averaging channels
                    if channels == 1 {
                        buf.extend_from_slice(data);
                    } else {
                        for chunk in data.chunks(channels) {
                            let sum: f32 = chunk.iter().sum();
                            buf.push(sum / channels as f32);
                        }
                    }
                },
                |err| eprintln!("[STT] Audio stream error: {}", err),
                None,
            )
            .map_err(|e| format!("Failed to build input stream: {}", e))?,
        cpal::SampleFormat::I16 => device
            .build_input_stream(
                &config.into(),
                move |data: &[i16], _: &cpal::InputCallbackInfo| {
                    let mut buf = buf.lock().unwrap();
                    if channels == 1 {
                        buf.extend(data.iter().map(|&s| s as f32 / 32768.0));
                    } else {
                        for chunk in data.chunks(channels) {
                            let sum: f32 = chunk.iter().map(|&s| s as f32 / 32768.0).sum();
                            buf.push(sum / channels as f32);
                        }
                    }
                },
                |err| eprintln!("[STT] Audio stream error: {}", err),
                None,
            )
            .map_err(|e| format!("Failed to build input stream: {}", e))?,
        format => return Err(format!("Unsupported sample format: {:?}", format)),
    };

    stream
        .play()
        .map_err(|e| format!("Failed to start stream: {}", e))?;

    Ok((stream, sample_rate))
}

#[cfg(feature = "stt")]
fn stt_transcribe(
    ctx: Arc<whisper_rs::WhisperContext>,
    mono_samples: Vec<f32>,
    input_sample_rate: u32,
) -> Result<String, String> {
    let input_rate = input_sample_rate as usize;
    let output_rate = 16000usize;

    // Resample to 16kHz for Whisper using linear interpolation
    let resampled = if input_rate != output_rate {
        let ratio = input_rate as f64 / output_rate as f64;
        let output_len = (mono_samples.len() as f64 / ratio) as usize;
        let mut output = Vec::with_capacity(output_len);
        for i in 0..output_len {
            let src_idx = i as f64 * ratio;
            let idx0 = src_idx as usize;
            let frac = src_idx - idx0 as f64;
            let s0 = mono_samples.get(idx0).copied().unwrap_or(0.0);
            let s1 = mono_samples.get(idx0 + 1).copied().unwrap_or(s0);
            output.push(s0 + (s1 - s0) * frac as f32);
        }
        output
    } else {
        mono_samples
    };

    // Run Whisper
    let mut state = ctx
        .create_state()
        .map_err(|e| format!("Failed to create whisper state: {}", e))?;

    let mut params =
        whisper_rs::FullParams::new(whisper_rs::SamplingStrategy::Greedy { best_of: 1 });
    params.set_language(Some("en"));
    params.set_print_special(false);
    params.set_print_progress(false);
    params.set_print_realtime(false);
    params.set_print_timestamps(false);
    params.set_suppress_blank(true);
    params.set_no_speech_thold(0.6);

    state
        .full(params, &resampled)
        .map_err(|e| format!("Whisper transcription failed: {}", e))?;

    let num_segments = state.full_n_segments();
    let mut result = String::new();
    for i in 0..num_segments {
        if let Some(segment) = state.get_segment(i) {
            if let Ok(segment_text) = segment.to_str_lossy() {
                result.push_str(&segment_text);
            }
        }
    }

    Ok(result.trim().to_string())
}

fn main() -> iced::Result {
    // First launch: bring V5's workspaces, remotes and tokens across before
    // anything creates the V6 config dir (TRU-168).
    config_import::import_v5_config_on_first_launch();

    // Print instance information for multi-instance support
    config::print_instance_info();

    // Start freeze detection watchdog
    start_freeze_watchdog();

    // Initialize the global agent-webview IPC channel before any webview can
    // post messages into it. The receiver is parked for the subscription to
    // take on first build.
    init_agent_ipc_channel();
    init_task_control_channel();

    // Load app icon from embedded PNG
    let icon = iced::window::icon::from_file_data(include_bytes!("../assets/icon.png"), None).ok();

    iced::application(App::new, App::update, App::view)
        .title(App::title)
        .window_size(Size {
            width: 1400.0,
            height: 800.0,
        })
        .window(iced::window::Settings {
            icon,
            ..Default::default()
        })
        .subscription(App::subscription)
        .run()
}

