#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BrowserAction {
    Opening,
    Focusing,
    Disconnecting,
}

/// The workspace bar's menus (TRU-192), anchored above the bar.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BarMenu {
    /// `Repos ▾`: this Mac's folder workspaces and a section per machine.
    Repos,
    /// `⋯`: help and the browser's less common actions.
    More,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BrowserBarState {
    Unavailable,
    Stopped,
    Running,
    Busy(BrowserAction),
    Error,
}

fn browser_bar_state(
    browser_available: bool,
    status: Option<&BrowserStatus>,
    action: Option<BrowserAction>,
    error: Option<&str>,
) -> BrowserBarState {
    if !browser_available {
        BrowserBarState::Unavailable
    } else if let Some(action) = action {
        BrowserBarState::Busy(action)
    } else if error.is_some() {
        BrowserBarState::Error
    } else if status.is_some_and(|status| status.state == BrowserState::Running) {
        BrowserBarState::Running
    } else {
        BrowserBarState::Stopped
    }
}

fn compact_browser_error(error: &str) -> String {
    const MAX_CHARS: usize = 40;
    let first_line = error.lines().next().unwrap_or(error).trim();
    let mut chars = first_line.chars();
    let summary: String = chars.by_ref().take(MAX_CHARS).collect();
    if chars.next().is_some() {
        format!("{summary}…")
    } else {
        summary
    }
}

/// The latest capture and its comparison partner: another target of the
/// same chat (TRU-176), preferring the same label, mode and viewport.
fn paired_browser_evidence(evidence: &[BrowserEvidence]) -> Vec<&BrowserEvidence> {
    let Some(anchor) = evidence.iter().max_by_key(|capture| capture.id) else {
        return Vec::new();
    };
    let candidates = || {
        evidence
            .iter()
            .filter(|capture| capture.owner == anchor.owner && capture.target != anchor.target)
    };
    let partner = candidates()
        .filter(|capture| {
            capture.label == anchor.label
                && capture.capture_mode == anchor.capture_mode
                && capture.viewport == anchor.viewport
        })
        .max_by_key(|capture| capture.id)
        .or_else(|| {
            candidates()
                .filter(|capture| capture.label == anchor.label)
                .max_by_key(|capture| capture.id)
        })
        .or_else(|| candidates().max_by_key(|capture| capture.id));
    let mut selected = evidence
        .iter()
        .filter(|capture| {
            capture.id == anchor.id || partner.is_some_and(|item| item.id == capture.id)
        })
        .collect::<Vec<_>>();
    selected.truncate(2);
    selected
}

