/// What the Viewer webview surface is presenting. The agent chat pages are
/// tracked separately via `App::agent_pages`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ViewerWebview {
    /// Hidden.
    None,
    /// Markdown / Excalidraw / HTML file viewer for the active tab's overlay.
    File,
    /// Plans viewer — URL-loaded surface served by warp on localhost.
    PlansViewer,
    /// The review pane (TRU-178), state in `App::review_pane`.
    Review,
}

/// What the active tab needs from the webview surfaces.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ActiveTabSurface {
    /// A terminal tab (or no tab): the Agent surface has nothing to show.
    Other,
    /// An agent tab showing its chat.
    AgentChat(usize),
    /// An agent tab whose chat is covered by its file viewer overlay or by
    /// the git diff panel for a selected file.
    AgentFileOverlay,
}

/// The workspace bar's height in logical pixels, border included.
const BAR_HEIGHT: f32 = 28.0;
/// How long the pointer rests on a bar item before its hint shows.
const BAR_HINT_DELAY: Duration = Duration::from_millis(400);
const BAR_HINT_HIDE_SCRIPT: &str = "window.__gittermHint && window.__gittermHint(null)";

/// The hover hint of a bar item (TRU-192): its text and the pointer's x in
/// window coordinates when the pointer entered, which stands for the item's
/// centre.
#[derive(Debug, Clone, PartialEq)]
struct BarHint {
    text: String,
    center_x: f32,
    /// The delay has passed, so the hint is on screen.
    shown: bool,
}

/// What draws the bar hint: an Iced overlay, or a page's `__gittermHint`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BarHintTarget {
    Iced,
    Webview(WebviewSurface),
}

/// A webview covers anything Iced draws above the bar only when it sits
/// directly on top of it, so with the terminal panel open (Iced content
/// between the two) or no webview showing, Iced draws the bubble.
fn bar_hint_target(visible: VisibleSurface, console_expanded: bool) -> BarHintTarget {
    if console_expanded {
        return BarHintTarget::Iced;
    }
    match visible {
        VisibleSurface::None => BarHintTarget::Iced,
        VisibleSurface::Viewer => BarHintTarget::Webview(WebviewSurface::Viewer),
        VisibleSurface::AgentChat(tab_id) => BarHintTarget::Webview(WebviewSurface::Agent(tab_id)),
    }
}

/// A rough bubble width for 10.5px Menlo text, enough to keep it on screen.
fn bar_hint_width(text: &str) -> f32 {
    text.chars().count() as f32 * 6.4 + 14.0
}

/// Move a bubble's centre so a bubble `width` wide stays inside `0..bound`
/// with a 4px margin (the page's or window's width).
fn clamp_hint_center(center: f32, width: f32, bound: f32) -> f32 {
    const MARGIN: f32 = 4.0;
    let half = width / 2.0;
    let low = half + MARGIN;
    let high = bound - half - MARGIN;
    if high < low {
        return bound / 2.0;
    }
    center.clamp(low, high)
}

/// The script that shows the hint on a page; the text goes in as a JSON
/// string so the page treats it as text.
fn bar_hint_show_script(text: &str, x: f32) -> String {
    let text = serde_json::to_string(text).unwrap_or_else(|_| "\"\"".to_string());
    format!("window.__gittermHint && window.__gittermHint({text}, {x})")
}

/// The one webview surface that should be on screen.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum VisibleSurface {
    None,
    Viewer,
    /// The Agent surface, showing this agent tab's chat.
    AgentChat(usize),
}

/// Pick the visible webview surface: at most one, Viewer over Agent, nothing
/// while the Usage view or the folder picker covers the content area
/// (`overlay_open`).
fn visible_webview_surface(
    viewer: ViewerWebview,
    active: ActiveTabSurface,
    overlay_open: bool,
) -> VisibleSurface {
    if overlay_open {
        return VisibleSurface::None;
    }
    if viewer != ViewerWebview::None {
        return VisibleSurface::Viewer;
    }
    match active {
        ActiveTabSurface::AgentChat(tab_id) => VisibleSurface::AgentChat(tab_id),
        ActiveTabSurface::Other | ActiveTabSurface::AgentFileOverlay => VisibleSurface::None,
    }
}

/// The full-window Usage view (TRU-145), opened from the bottom of the
/// workspace rail. It never touches the workspace or tab selection, so
/// closing it lands on exactly what was showing.
#[derive(Debug, Clone, Default, PartialEq)]
struct UsageViewState {
    open: bool,
    /// The repo the view is narrowed to: its row key and display name.
    repo: Option<(gitterm::usage::RepoKey, String)>,
}

/// What can happen to the Usage view.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UsageViewInput {
    /// The rail glyph or Cmd+Shift+U.
    Toggle,
    /// Esc.
    Close,
    /// A workspace button on the rail (or Ctrl+1-9).
    SelectWorkspace(usize),
}

/// Apply `input` to the Usage view while `active_workspace` is showing and
/// return the workspace to show next. Opening and closing keep the
/// selection; selecting a workspace closes the view. Closing drops the
/// repo filter, so the view reopens app-wide.
fn usage_view_step(
    state: &mut UsageViewState,
    active_workspace: usize,
    input: UsageViewInput,
) -> usize {
    let (open, workspace) = match input {
        UsageViewInput::Toggle => (!state.open, active_workspace),
        UsageViewInput::Close => (false, active_workspace),
        UsageViewInput::SelectWorkspace(target) => (false, target),
    };
    state.open = open;
    if !open {
        state.repo = None;
    }
    workspace
}

/// How many agent chat pages may be alive at once. Showing a tab without a
/// page beyond this destroys the least recently shown one; that tab is
/// rebuilt and replayed from its buffer when it is next shown.
const MAX_AGENT_PAGES: usize = 4;

/// How `App::show_agent_webview` brings an agent tab's chat on screen.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentSurfaceAction {
    /// This tab's page is alive and was the last one shown: show it, DOM intact.
    Reveal,
    /// This tab's page is alive but another tab's page was shown last: hide
    /// that one and show this one. No reset, no replay.
    SwitchTab,
    /// This tab has no live page: build one and replay the tab's conversation
    /// (evicting the least recently shown page past `MAX_AGENT_PAGES`).
    Create,
}

/// `page_alive`: whether `tab_id`'s page has been built. `front_page`: the
/// tab whose page was shown last (`App::agent_pages[0]`).
fn agent_surface_action(
    page_alive: bool,
    front_page: Option<usize>,
    tab_id: usize,
) -> AgentSurfaceAction {
    if !page_alive {
        AgentSurfaceAction::Create
    } else if front_page == Some(tab_id) {
        AgentSurfaceAction::Reveal
    } else {
        AgentSurfaceAction::SwitchTab
    }
}

/// Move `tab_id` to the front of `pages` (most recently shown first), adding
/// it if absent, and return the tabs pushed past `cap`, whose pages the
/// caller destroys. Least recently shown is evicted first.
fn promote_agent_page(pages: &mut Vec<usize>, tab_id: usize, cap: usize) -> Vec<usize> {
    pages.retain(|&id| id != tab_id);
    pages.insert(0, tab_id);
    if pages.len() > cap {
        pages.split_off(cap.max(1))
    } else {
        Vec::new()
    }
}

