fn terminal_event_should_queue_redraw(
    window_focused: bool,
    visible_terminal_id: Option<usize>,
    event_terminal_id: usize,
) -> bool {
    window_focused && visible_terminal_id == Some(event_terminal_id)
}

#[derive(Debug, Default, PartialEq, Eq)]
struct TerminalRedrawQueue {
    main: bool,
    bottom: bool,
}

impl TerminalRedrawQueue {
    fn queue_main(&mut self) {
        self.main = true;
    }

    fn queue_bottom(&mut self) {
        self.bottom = true;
    }

    fn is_pending(&self) -> bool {
        self.main || self.bottom
    }

    fn take(&mut self) -> (bool, bool) {
        let pending = (self.main, self.bottom);
        *self = Self::default();
        pending
    }

    fn clear(&mut self) {
        *self = Self::default();
    }
}

fn expand_home_path(path: &str) -> PathBuf {
    if let Some(rest) = path.strip_prefix("~/") {
        if let Some(home) = dirs::home_dir() {
            return home.join(rest);
        }
    }
    PathBuf::from(path)
}

fn remote_session_definition_from_config(config: &RemoteSessionConfig) -> RemoteSessionDefinition {
    RemoteSessionDefinition {
        host: RemoteHostConfig {
            name: config.host_name.clone(),
            ssh_target: config.ssh_target.clone(),
            identity_file: expand_home_path(&config.identity_file),
            tmux_path: config.tmux_path.clone(),
        },
        label: config.label.clone(),
        session_name: config.session_name.clone(),
        remote_dir: config.remote_dir.clone(),
        shell_command: config.shell_command.clone(),
        codex_command: config.codex_command.clone(),
        claude_command: config.claude_command.clone(),
    }
}

fn remote_session_config_from_definition(
    definition: &RemoteSessionDefinition,
) -> RemoteSessionConfig {
    RemoteSessionConfig {
        label: definition.label.clone(),
        host_name: definition.host.name.clone(),
        ssh_target: definition.host.ssh_target.clone(),
        identity_file: definition.host.identity_file.to_string_lossy().to_string(),
        tmux_path: definition.host.tmux_path.clone(),
        session_name: definition.session_name.clone(),
        remote_dir: definition.remote_dir.clone(),
        shell_command: definition.shell_command.clone(),
        codex_command: definition.codex_command.clone(),
        claude_command: definition.claude_command.clone(),
    }
}

fn remote_session_definitions_from_config(
    configs: &[RemoteSessionConfig],
) -> Vec<RemoteSessionDefinition> {
    configs
        .iter()
        .map(remote_session_definition_from_config)
        .collect()
}

fn push_remote_agent_config(definitions: &mut Vec<RemoteAgentConfig>, agent: RemoteAgentConfig) {
    if !definitions.iter().any(|existing| existing.id == agent.id) {
        definitions.push(agent);
    }
}

/// Insert or update an agent by id. Updates touch only the fields the
/// connect form edits; hand-maintained `shell_command` / `session_commands`
/// on an existing entry are preserved.
fn upsert_remote_agent_config(definitions: &mut Vec<RemoteAgentConfig>, agent: RemoteAgentConfig) {
    if let Some(existing) = definitions
        .iter_mut()
        .find(|existing| existing.id == agent.id)
    {
        existing.name = agent.name;
        existing.endpoint = agent.endpoint;
        existing.auth = agent.auth;
    } else {
        definitions.push(agent);
    }
}

/// Upsert a single agent into remote-agents.json, leaving every other
/// entry exactly as the user maintains it on disk.
fn save_remote_agent_to_disk(agent: &RemoteAgentConfig) {
    let mut file = RemoteAgentsFile::load().unwrap_or_default();
    upsert_remote_agent_config(&mut file.remote_agents, agent.clone());
    file.save();
}

/// Derive a stable id from a display name: lowercase alphanumerics with
/// single dashes, e.g. "Mac mini" -> "mac-mini".
fn remote_agent_id_slug(name: &str) -> String {
    let mut slug = String::new();
    let mut prev_dash = true;
    for ch in name.chars() {
        if ch.is_ascii_alphanumeric() {
            slug.push(ch.to_ascii_lowercase());
            prev_dash = false;
        } else if !prev_dash {
            slug.push('-');
            prev_dash = true;
        }
    }
    let slug = slug.trim_end_matches('-');
    if slug.is_empty() {
        "remote".to_string()
    } else {
        slug.to_string()
    }
}

/// Store a pasted token under ~/.config/gitterm-v6/tokens/<id>.token and
/// return the path. Owner-only permissions on unix.
fn write_remote_agent_token(remote_id: &str, token: &str) -> std::io::Result<PathBuf> {
    let dir = config::global_config_dir().join("tokens");
    std::fs::create_dir_all(&dir)?;
    let path = dir.join(format!("{remote_id}.token"));
    std::fs::write(&path, format!("{token}\n"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600))?;
    }
    Ok(path)
}

fn remote_agent_for_session<'a>(
    definitions: &'a [RemoteAgentConfig],
    session: &RemoteSessionDefinition,
) -> Option<&'a RemoteAgentConfig> {
    definitions.iter().find(|agent| {
        agent.id == session.host.name
            || agent.name == session.host.name
            || agent.name.eq_ignore_ascii_case(&session.host.name)
    })
}

fn remote_agent_location_for_session(
    definitions: &[RemoteAgentConfig],
    session: &RemoteSessionDefinition,
) -> Option<WorkspaceLocation> {
    let agent = remote_agent_for_session(definitions, session)?;
    Some(WorkspaceLocation::RemoteAgent {
        remote_id: agent.id.clone(),
        workspace_id: session.session_name.clone(),
        root: session.remote_dir.clone(),
    })
}

/// Cached chat index for one remote machine (TRU-78 slice 4).
#[derive(Debug, Default)]
struct RemoteChatState {
    entries: Vec<chats::ChatIndexEntry>,
    loading: bool,
    loaded_at: Option<Instant>,
    /// Last fetch failure; entries (if any) are a stale cache while set.
    error: Option<String>,
}

fn remote_agent_client_config(agent: RemoteAgentConfig) -> RemoteAgentClientConfig {
    let token_ref = match agent.auth {
        config::RemoteAgentAuthConfig::Token { token_ref } => token_ref,
    };
    RemoteAgentClientConfig {
        remote_id: agent.id,
        name: agent.name,
        endpoint: agent.endpoint,
        token_ref,
    }
}

fn push_remote_session_definition(
    definitions: &mut Vec<RemoteSessionDefinition>,
    session: RemoteSessionDefinition,
) {
    if !definitions
        .iter()
        .any(|existing| existing.session_name == session.session_name)
    {
        definitions.push(session);
    }
}

fn remote_codex_session_name(session: &RemoteSessionDefinition) -> String {
    format!("{}-codex", session.session_name)
}

fn remote_claude_session_name(session: &RemoteSessionDefinition) -> String {
    format!("{}-claude", session.session_name)
}

fn remote_workspace_name(session: &RemoteSessionDefinition) -> String {
    format!("{}:{}", session.host.name, session.label)
}

fn remote_tab_title_for_startup_command(
    session: &RemoteSessionDefinition,
    startup_command: Option<&str>,
) -> String {
    let Some(startup_command) = startup_command else {
        return "Shell".to_string();
    };
    if startup_command.contains(&remote_codex_session_name(session)) {
        "Codex".to_string()
    } else if startup_command.contains(&remote_claude_session_name(session)) {
        "Claude".to_string()
    } else if startup_command.contains(&session.session_name) {
        "Shell".to_string()
    } else {
        "Remote".to_string()
    }
}

fn default_remote_session_definitions() -> Vec<RemoteSessionDefinition> {
    remote_session_definitions_from_config(&config::default_remote_sessions())
}

fn workspace_location_from_config(
    config: Option<&WorkspaceLocationConfig>,
    local_dir: &Path,
    remote_session: Option<&RemoteSessionDefinition>,
    remote_agents: &[RemoteAgentConfig],
) -> WorkspaceLocation {
    match config {
        Some(WorkspaceLocationConfig::Local { root }) => WorkspaceLocation::Local {
            root: PathBuf::from(root),
        },
        Some(WorkspaceLocationConfig::RemoteAgent {
            remote_id,
            workspace_id,
            root,
        }) => WorkspaceLocation::RemoteAgent {
            remote_id: remote_id.clone(),
            workspace_id: workspace_id.clone(),
            root: root.clone(),
        },
        None => {
            if let Some(session) = remote_session {
                remote_agent_location_for_session(remote_agents, session).unwrap_or_else(|| {
                    WorkspaceLocation::LegacyRemoteSession {
                        session_name: session.session_name.clone(),
                        root: session.remote_dir.clone(),
                    }
                })
            } else {
                WorkspaceLocation::Local {
                    root: local_dir.to_path_buf(),
                }
            }
        }
    }
}

fn workspace_location_config_from_location(
    location: &WorkspaceLocation,
) -> Option<WorkspaceLocationConfig> {
    match location {
        WorkspaceLocation::Local { root } => {
            let _ = root;
            None
        }
        WorkspaceLocation::LegacyRemoteSession { session_name, root } => {
            let _ = (session_name, root);
            None
        }
        WorkspaceLocation::RemoteAgent {
            remote_id,
            workspace_id,
            root,
        } => Some(WorkspaceLocationConfig::RemoteAgent {
            remote_id: remote_id.clone(),
            workspace_id: workspace_id.clone(),
            root: root.clone(),
        }),
    }
}

fn workspace_config_dir(workspace: &Workspace) -> String {
    match &workspace.location {
        WorkspaceLocation::RemoteAgent { root, .. } => root.clone(),
        WorkspaceLocation::Local { .. } | WorkspaceLocation::LegacyRemoteSession { .. } => {
            workspace.dir.to_string_lossy().to_string()
        }
    }
}

fn path_strings(paths: &[PathBuf]) -> Vec<String> {
    paths
        .iter()
        .map(|path| path.to_string_lossy().into_owned())
        .collect()
}

/// The main checkout of a task's repository from its git common dir
/// (`<checkout>/.git`); `None` for a bare or otherwise laid-out repo.
fn task_main_checkout(common_dir: &Path) -> Option<PathBuf> {
    (common_dir.file_name()? == ".git").then(|| common_dir.parent().map(Path::to_path_buf))?
}

/// A repo's dir as `workspaces.json` writes it (see `workspace_config_dir`).
fn repo_config_dir(repo: &RepoState) -> String {
    match &repo.location {
        WorkspaceLocation::RemoteAgent { root, .. } => root.clone(),
        WorkspaceLocation::Local { .. } | WorkspaceLocation::LegacyRemoteSession { .. } => {
            repo.dir.to_string_lossy().to_string()
        }
    }
}

/// A repo as the `repos` section of `workspaces.json` stores it; `None`
/// for a legacy remote workspace's repo, which is never stored (see
/// `WorkspaceConfig::is_legacy_remote`).
fn repo_config_of(repo: &RepoState) -> Option<RepoConfig> {
    if matches!(repo.key, RepoKey::LegacyRemote { .. }) {
        return None;
    }
    Some(RepoConfig {
        dir: repo_config_dir(repo),
        location: workspace_location_config_from_location(&repo.location),
        run_command: repo.run_command.clone(),
        env: repo.env.clone(),
        // Terminals are the workspace's (stored on its entry); this field
        // is only read, from files written before they were.
        bottom_terminals: Vec::new(),
    })
}

/// Replaces the stored repo with `repo`'s key, or adds it.
fn upsert_repo_config(stored: &mut Vec<RepoConfig>, repo: RepoConfig) {
    let key = repo.key();
    match stored.iter_mut().find(|known| known.key() == key) {
        Some(known) => *known = repo,
        None => stored.push(repo),
    }
}

/// The `repos` section to write: every open repo (`open`, registry
/// order), then each stored repo a closed workspace still lists. A repo
/// no workspace lists is dropped.
fn repos_section(
    open: Vec<RepoConfig>,
    stored: &[RepoConfig],
    closed: &[WorkspaceConfig],
) -> Vec<RepoConfig> {
    let mut section = open;
    let listed_by_closed: Vec<RepoKey> = closed
        .iter()
        .flat_map(|cfg| cfg.repos.iter().filter_map(|dir| cfg.repo_key(dir)))
        .collect();
    for repo in stored {
        let key = repo.key();
        if listed_by_closed.contains(&key) && !section.iter().any(|known| known.key() == key) {
            section.push(repo.clone());
        }
    }
    section
}

fn remote_agent_root(location: &WorkspaceLocation) -> Option<&str> {
    match location {
        WorkspaceLocation::RemoteAgent { root, .. } => Some(root.as_str()),
        WorkspaceLocation::Local { .. } | WorkspaceLocation::LegacyRemoteSession { .. } => None,
    }
}

/// Why the folder picker is open; decides what "Use this folder" does.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FolderPickerPurpose {
    /// New workspace ("+", machine menus): create a workspace rooted at
    /// the folder on the chosen machine.
    NewWorkspace,
    /// Open Folder (Cmd+O, Option+Shift+T, the empty-state button): add a
    /// tab for the folder, in a workspace on the chosen machine.
    OpenFolder,
    /// "+ add repo" in a workspace's overview (TRU-180): list the folder
    /// in the open workspace with this uid. This Mac only.
    AddRepo(u64),
}

/// The in-app folder picker (TRU-149), one for every machine. Listings
/// come through `WorkspaceSource` + `FilesState` exactly like the Files
/// sidebar, from a source rooted at the filesystem root so any directory
/// can be chosen.
#[derive(Debug, Clone)]
struct FolderPicker {
    purpose: FolderPickerPurpose,
    /// Machine being browsed (None = this Mac).
    remote_id: Option<String>,
    files: FilesState,
    /// Path field contents: follows navigation, editable to jump.
    path_input: String,
    /// Inline error for a typed path that is not a directory.
    path_error: Option<String>,
    /// Sequence of typed-path checks; any navigation supersedes a pending
    /// one so a slow answer can't jump the picker.
    typed_seq: u64,
    /// Opened at "/" because the remote's home was not known yet: the
    /// handshake that reports it moves the picker there, unless the user
    /// navigated meanwhile.
    awaiting_home: bool,
}

/// Where the folder picker opens on a machine: the folder last chosen
/// there this session, else the machine's home, else "/".
fn folder_picker_start_dir(last_chosen: Option<&str>, home: Option<&str>) -> String {
    [last_chosen, home]
        .into_iter()
        .flatten()
        .find(|dir| !dir.is_empty())
        .unwrap_or("/")
        .to_string()
}

/// The Chats row's facts line (TRU-166): up to three issue keys, three
/// repos touched (most edited first) and the fan-out counts, e.g.
/// "PRJ-101 PRJ-102 · infra auth-service +12 · 38 subagents · 2 workers".
fn chat_facts_line(facts: &chat_facts::ChatFacts) -> Option<String> {
    fn capped(items: Vec<String>, max: usize) -> Option<String> {
        if items.is_empty() {
            return None;
        }
        let mut line = items
            .iter()
            .take(max)
            .cloned()
            .collect::<Vec<_>>()
            .join(" ");
        if items.len() > max {
            line.push_str(&format!(" +{}", items.len() - max));
        }
        Some(line)
    }
    let parts: Vec<String> = [
        capped(facts.issue_keys.clone(), 3),
        capped(facts.edited_repo_names(), 3),
        facts.fan_out_line(),
    ]
    .into_iter()
    .flatten()
    .collect();
    (!parts.is_empty()).then(|| parts.join(" · "))
}

/// The picker's "Recent" list for one machine: distinct repo roots from
/// its chat index, most recent first, then its open workspaces' dirs; at
/// most `max`. Chats whose directory is gone are skipped.
fn folder_picker_recents(
    entries: &[chats::ChatIndexEntry],
    open_dirs: &[PathBuf],
    max: usize,
) -> Vec<PathBuf> {
    let mut live: Vec<&chats::ChatIndexEntry> =
        entries.iter().filter(|entry| !entry.dead_cwd).collect();
    live.sort_by_key(|entry| std::cmp::Reverse(entry.mtime));
    let mut recents: Vec<PathBuf> = Vec::new();
    let candidates = live
        .iter()
        .map(|entry| entry.group_root())
        .chain(open_dirs.iter().map(PathBuf::as_path));
    for dir in candidates {
        if recents.len() >= max {
            break;
        }
        if !recents.iter().any(|seen| seen == dir) {
            recents.push(dir.to_path_buf());
        }
    }
    recents
}

/// Resolve the picker's path field: trimmed, a leading "~" expanded to
/// the machine's `home`, and absolute. The error is shown inline.
fn folder_picker_typed_path(input: &str, home: Option<&str>) -> Result<String, String> {
    let input = input.trim();
    if input.is_empty() {
        return Err("Type a folder path".to_string());
    }
    let resolved = if input == "~" || input.starts_with("~/") {
        let Some(home) = home.filter(|home| !home.is_empty()) else {
            return Err(
                "This machine's home folder is not known; type an absolute path".to_string(),
            );
        };
        format!("{}{}", home.trim_end_matches('/'), &input[1..])
    } else {
        input.to_string()
    };
    if !(resolved.starts_with('/') || Path::new(&resolved).is_absolute()) {
        return Err(format!("{resolved} is not an absolute path"));
    }
    Ok(resolved)
}

/// A picker path for display, with the machine's home shown as "~".
fn folder_picker_tilde(path: &str, home: Option<&str>) -> String {
    let Some(home) = home
        .map(|home| home.trim_end_matches('/'))
        .filter(|home| !home.is_empty())
    else {
        return path.to_string();
    };
    match path.strip_prefix(home) {
        Some("") => "~".to_string(),
        Some(rest) if rest.starts_with('/') => format!("~{rest}"),
        _ => path.to_string(),
    }
}

