    #[test]
    fn resume_as_chat_is_offered_only_for_unowned_claude_chats_with_a_live_cwd() {
        let local = ChatMachine::Local;
        let remote_chat = ChatMachine::Remote { claude_chat: true };
        let old_remote = ChatMachine::Remote { claude_chat: false };
        let claude = chat_entry(chats::ChatBackend::Claude, false);
        assert!(can_resume_as_chat(&claude, local, false));
        assert!(
            can_resume_as_chat(&claude, remote_chat, false),
            "remote chat on an agent that runs Claude chats"
        );
        assert!(
            !can_resume_as_chat(&claude, old_remote, false),
            "older or unreachable agent: Resume as Session only"
        );
        for machine in [local, remote_chat] {
            assert!(
                !can_resume_as_chat(&claude, machine, true),
                "a tab owns it: Go to Session instead"
            );
            assert!(
                !can_resume_as_chat(
                    &chat_entry(chats::ChatBackend::Claude, true),
                    machine,
                    false
                ),
                "dead cwd: only the rescue action"
            );
            for backend in [chats::ChatBackend::Codex, chats::ChatBackend::Pi] {
                assert!(!can_resume_as_chat(
                    &chat_entry(backend, false),
                    machine,
                    false
                ));
            }
        }
    }

    #[test]
    fn resumed_chat_session_uses_new_chat_defaults_and_resumes_with_history() {
        let mut defaults = config::ChatDefaults {
            default_model: "opus".to_string(),
            default_effort: Some("high".to_string()),
            remember_last: false,
            last: Some(config::ChatSelection {
                model: "sonnet".to_string(),
                effort: None,
            }),
            ..config::ChatDefaults::default()
        };
        let session = resumed_claude_chat_session(&defaults, "3f2a");
        let tab::AgentBackendConfig::Claude {
            model,
            permission_mode,
            effort,
        } = &session.config
        else {
            panic!("expected a Claude config, got {:?}", session.config);
        };
        assert_eq!(model, "opus");
        assert_eq!(effort.as_deref(), Some("high"));
        assert_eq!(
            permission_mode.as_deref(),
            Some(tab::DEFAULT_CLAUDE_PERMISSION_MODE)
        );
        // Same path a restored chat tab takes: `show_agent_webview` calls
        // `start_agent_history_load`, which reads `history_to_load`.
        assert_eq!(session.history_to_load(), Some("3f2a"));
        // The first prompt spawns Claude with `--resume=<id>`.
        let spawn = session
            .claude_session_config(PathBuf::from("/tmp/repo/sub"), Vec::new(), false, None)
            .expect("claude config");
        assert_eq!(spawn.resume.as_deref(), Some("3f2a"));
        assert_eq!(spawn.model.as_deref(), Some("opus"));
        // Without the workspace's switch, the resume starts without Claude
        // in Chrome (TRU-181).
        let args = spawn.args();
        assert!(args.contains(&"--no-chrome".to_string()), "{args:?}");
        assert!(args.contains(&"--resume=3f2a".to_string()), "{args:?}");

        // A remembered selection wins, exactly as for "New chat".
        defaults.remember_last = true;
        let session = resumed_claude_chat_session(&defaults, "3f2a");
        assert!(matches!(
            &session.config,
            tab::AgentBackendConfig::Claude { model, effort: None, .. } if model == "sonnet"
        ));
    }

    #[test]
    fn session_tab_label_reads_a_chats_title_over_its_folder_name() {
        // Two chats in one folder no longer read the same.
        assert_eq!(
            session_tab_label(Some("Fix PRJ-101 login"), "acme-portal", false, false),
            "Fix PRJ-101 login"
        );
        // Long titles are cut to the strip's width, on chars.
        let label = session_tab_label(
            Some("Migrate the acme billing service to the new queue"),
            "acme-portal",
            false,
            false,
        );
        assert_eq!(label, "Migrate the acme bi…");
        assert_eq!(label.chars().count(), SESSION_TAB_LABEL_CHARS);
        let accented = session_tab_label(Some("Résumé café thème naïve über"), "x", false, false);
        assert_eq!(accented.chars().count(), SESSION_TAB_LABEL_CHARS);
        // A title is free text: a leading "/" is not a path.
        assert_eq!(
            session_tab_label(Some("/review PRJ-101"), "acme-portal", false, false),
            "/review PRJ-101"
        );
    }

    #[test]
    fn session_tab_label_keeps_todays_label_without_a_title() {
        // Not indexed yet, or a blank title: the folder name as today.
        assert_eq!(
            session_tab_label(None, "acme-portal", false, false),
            "acme-portal"
        );
        assert_eq!(
            session_tab_label(Some("   "), "acme-portal", false, false),
            "acme-portal"
        );
        // Terminal tabs: path shortening, attention markers and the cut.
        assert_eq!(
            session_tab_label(None, "/tmp/acme/portal", false, false),
            "portal"
        );
        assert_eq!(
            session_tab_label(None, "/tmp/acme/portal", false, true),
            "/tmp/acme/portal"
        );
        assert_eq!(
            session_tab_label(None, "* acme-portal", true, false),
            "acme-portal"
        );
        assert_eq!(
            session_tab_label(None, "a-very-long-terminal-title", false, false),
            "a-very-long-termina…"
        );
    }

    /// A root chat `id` titled `title`, last touched `secs` after the epoch.
    fn note_chat(id: &str, title: &str, latest: Option<&str>, secs: u64) -> chats::ChatIndexEntry {
        chats::ChatIndexEntry {
            id: id.to_string(),
            title: title.to_string(),
            latest: latest.map(str::to_string),
            mtime: std::time::SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(secs),
            ..chat_entry(chats::ChatBackend::Claude, false)
        }
    }

    #[test]
    fn park_note_prefill_reads_the_most_recent_root_chats_latest_line() {
        let older = note_chat(
            "a",
            "Set up acme billing",
            Some("Add the PRJ-101 test"),
            100,
        );
        let newer = note_chat("b", "Fix acme login", Some("Ship the redirect fix"), 200);
        assert_eq!(
            park_note_prefill(&[&older, &newer]),
            "Ship the redirect fix"
        );

        // No latest line: the title.
        let titled = note_chat("c", "Fix acme login", None, 300);
        assert_eq!(park_note_prefill(&[&older, &titled]), "Fix acme login");

        // A newer child folds under its coordinator and never supplies it.
        let mut child = note_chat("d", "Worker: run the tests", None, 400);
        child.root_id = Some("b".to_string());
        assert_eq!(
            park_note_prefill(&[&newer, &child]),
            "Ship the redirect fix"
        );

        // No chats: an empty note.
        assert_eq!(park_note_prefill(&[]), "");
    }

